function Song(title) {
  this.title = title;
}

Song.play = function () {
  return "on the function";
};

Song.prototype.play = function () {
  return "Playing " + this.title;
};

const song = new Song("Blue");

console.log(song.play(), Song.play());
console.log(Object.getPrototypeOf(song) === Song.prototype);
console.log(Object.getPrototypeOf(Song) === Song.prototype);
console.log(typeof song.prototype, typeof Song.prototype);
